(function(){const label='Préparation DSN',beforeDsnRender=window.render;const key=()=>company+'|'+period();
window.saveDsnPreparation=function(){const form=$('#form'),data=new FormData(form),record={documents:{},selected:{},updatedAt:new Date().toISOString()};for(const [name,value]of data){if(name.startsWith('doc:'))record.documents[name.slice(4)]=value;if(name.startsWith('bulletin:'))record.selected[name.slice(9)]=value;}record.deadline=data.get('deadline');record.deadlineConfirmed=data.get('deadlineConfirmed')==='on';record.source=data.get('source');const k=key(),before=db.dsnPreparation?.[k];db.dsnPreparation=db.dsnPreparation||{};db.dsnPreparation[k]=record;if(!save()){if(before)db.dsnPreparation[k]=before;else delete db.dsnPreparation[k];return;}$('#modal').close();render();toast('Dossier de préparation DSN enregistré dans ce navigateur.');};
window.editDsnPreparation=function(){const a=DsnPreparation.audit(db,company,period());extendedForm('<h2>Dossier DSN · '+esc(period())+'</h2><p>Suivi documentaire uniquement. « Reçu » indique qu’une pièce est disponible, sans valider son contenu.</p>'+section('Échéance à confirmer',field('deadline','Date limite DSN retenue',a.record.deadline||'','date')+`<label><input type="checkbox" name="deadlineConfirmed" ${a.record.deadlineConfirmed?'checked':''}> Échéance vérifiée sur une source applicable</label>`+field('source','Référence de l’échéance (sans identifiants de connexion)',a.record.source||'')+`<p class="wide muted">La date de paiement du salaire au 5 ne détermine pas à elle seule l’échéance DSN.</p>`)+section('Pièces du dossier',a.documents.map(d=>selectField('doc:'+d.id,d.label,d.status,['À demander','Reçu','À vérifier','Non applicable'])).join(''))+section('Bulletins retenus pour le rapprochement',a.employees.map(p=>`<label>${esc(p.name)}<select name="bulletin:${esc(p.id)}"><option value="">Choisir explicitement une version</option>${p.documents.map(d=>`<option value="${esc(d.id)}" ${d.id===p.selectedId?'selected':''}>${esc(new Date(d.createdAt).toLocaleString('fr-FR'))} · brut ${esc(euroFmt(d.gross))}${d.revises?' · révision':''}</option>`).join('')}</select></label>`).join('')||'<p>Aucun salarié identifié sur cette période.</p>'),()=>{const form=$('#form');if(form.elements.deadlineConfirmed.checked&&(!form.elements.deadline.value||!form.elements.source.value.trim()))throw Error('Renseignez la date et sa référence avant de confirmer l’échéance.');window.saveDsnPreparation();return false;});};
window.render=function(){if(view!==label)return beforeDsnRender();document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.textContent===label));const a=DsnPreparation.audit(db,company,period()),c=db.companies.find(c=>c.id===company);$('#app').innerHTML=head('Préparer votre DSN.','Un dossier par entreprise et par mois, à rapprocher de la paie validée.',`<button class="btn" onclick="editDsnPreparation()">Compléter le dossier DSN</button>`)+`<p class="notice">Brouillon de préparation · aucun fichier DSN généré ni dépôt effectué. Les bulletins actuels sont des documents de test.</p><div class="stats"><div class="card"><span>Salariés sur la période</span><strong>${a.employees.length}</strong></div><div class="card"><span>Bulletins choisis</span><strong>${a.selectedCount}</strong></div><div class="card"><span>Données à compléter</span><strong>${a.missing}</strong></div><div class="card"><span>Pièces reçues</span><strong>${a.documents.filter(d=>d.status==='Reçu').length}/${a.documents.length}</strong></div></div><section class="panel"><h2>${esc(c.name)} · ${esc(a.period)}</h2><p>Échéance DSN : <strong>${esc(a.record.deadline||'À définir')}</strong> · ${a.record.deadlineConfirmed?'confirmée manuellement avec référence':'à vérifier'}${a.record.source?' · '+esc(a.record.source):''}</p><p class="muted">Paiement des salaires et dépôt DSN sont suivis séparément.</p><table><thead><tr><th>Entreprise / établissement</th><th>État</th></tr></thead><tbody>${a.checks.map(x=>`<tr><td>${esc(x.label)}${x.note?'<small>'+esc(x.note)+'</small>':''}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></section><section class="panel" style="margin-top:16px"><h2>Salariés et contrats</h2>${a.employees.map(p=>`<details><summary>${esc(p.name)} · ${p.selected?'bulletin choisi':'bulletin à choisir'}</summary><p>${p.documents.length} version(s) de bulletin. ${p.selected?'Brut de la version retenue : '+euroFmt(p.selected.gross)+'.':'Aucune version n’est retenue automatiquement.'}</p><table><tr><th>Donnée</th><th>État</th></tr>${p.fields.map(f=>`<tr><td>${esc(f.label)}</td><td>${esc(f.status)}</td></tr>`).join('')}</table><p class="muted">Identité DSN et NIR / NTT : intégration sécurisée à prévoir. Aucun NIR n’est demandé ici.</p>${p.selected?.issues.length?'<p class="error">Contrôles du bulletin : '+p.selected.issues.map(esc).join(' ; ')+'</p>':''}</details>`).join('')||'<p>Aucun salarié identifié. Vérifiez les dates de contrats et les entrées / sorties du mois.</p>'}</section><section class="panel" style="margin-top:16px"><h2>Documents à réunir</h2><table><tr><th>Pièce</th><th>Suivi</th></tr>${a.documents.map(d=>`<tr><td>${esc(d.label)}</td><td>${esc(d.status)}</td></tr>`).join('')}</table><p class="muted">Pour commencer : un salarié, son contrat, son bulletin de référence et son relevé d’heures anonymisés. DSN antérieures, CRM et fiches organismes si disponibles.</p></section><section class="panel" style="margin-top:16px"><h2>Avant une génération DSN</h2><ul>${a.blockers.map(b=>'<li>'+esc(b)+'</li>').join('')}</ul><p>Prochaine étape : compléter le dossier pilote et rapprocher la paie. Les signalements arrêt / reprise / fin de contrat seront traités dans une étape dédiée.</p><a href="https://www.net-entreprises.fr/declaration/norme-et-documentation-dsn/" target="_blank" rel="noopener">Norme et documentation officielle</a></section>`;};
if(!Array.from(document.querySelectorAll('#nav button')).some(b=>b.textContent===label)){const button=document.createElement('button');button.textContent=label;button.onclick=()=>go(label);$('#nav').appendChild(button);}render();})();
